SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'admin',status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(120) PRIMARY KEY,setting_value LONGTEXT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_code VARCHAR(60) NOT NULL UNIQUE,city VARCHAR(120) NOT NULL DEFAULT '',area VARCHAR(190) NOT NULL DEFAULT '',address TEXT NULL,media_type VARCHAR(80) NOT NULL DEFAULT 'Billboard',lighting VARCHAR(20) NOT NULL DEFAULT 'FL',facing VARCHAR(80) NOT NULL DEFAULT 'Upper',size VARCHAR(60) NOT NULL DEFAULT '',width DECIMAL(10,2) NULL,height DECIMAL(10,2) NULL,orientation VARCHAR(50) NOT NULL DEFAULT '',ownership VARCHAR(80) NOT NULL DEFAULT 'Owned',availability VARCHAR(40) NOT NULL DEFAULT 'Available',vendor_id BIGINT UNSIGNED NULL,vendor_name VARCHAR(190) NOT NULL DEFAULT '',meter_no VARCHAR(100) NOT NULL DEFAULT '',monthly_cost DECIMAL(15,2) NOT NULL DEFAULT 0,monthly_rate DECIMAL(15,2) NOT NULL DEFAULT 0,latitude DECIMAL(11,8) NULL,longitude DECIMAL(11,8) NULL,maps_url TEXT NULL,gps VARCHAR(190) NOT NULL DEFAULT '',notes TEXT NULL,flags LONGTEXT NULL,record_status VARCHAR(20) NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY city(city),KEY availability(availability),KEY media_type(media_type),KEY record_status(record_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,client_name VARCHAR(190) NOT NULL,company VARCHAR(190) NOT NULL DEFAULT '',primary_contact VARCHAR(190) NOT NULL DEFAULT '',email VARCHAR(190) NOT NULL DEFAULT '',phone VARCHAR(60) NOT NULL DEFAULT '',billing_address TEXT NULL,gst_number VARCHAR(80) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'active',notes TEXT NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY client_name(client_name),KEY status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_code VARCHAR(80) NOT NULL DEFAULT '',parent_campaign VARCHAR(120) NOT NULL DEFAULT '',site_id BIGINT UNSIGNED NOT NULL,site_code VARCHAR(60) NOT NULL,client_id BIGINT UNSIGNED NULL,client VARCHAR(190) NOT NULL DEFAULT '',brand VARCHAR(190) NOT NULL DEFAULT '',campaign_name VARCHAR(190) NOT NULL DEFAULT '',booking_date DATE NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,mounting_date DATE NULL,printing_status VARCHAR(40) NOT NULL DEFAULT 'Pending',mounting_status VARCHAR(40) NOT NULL DEFAULT 'Pending',validation_15_date DATE NULL,final_validation_date DATE NULL,revenue DECIMAL(15,2) NOT NULL DEFAULT 0,vendor_cost DECIMAL(15,2) NOT NULL DEFAULT 0,printing_cost DECIMAL(15,2) NOT NULL DEFAULT 0,mounting_cost DECIMAL(15,2) NOT NULL DEFAULT 0,electricity_cost DECIMAL(15,2) NOT NULL DEFAULT 0,other_cost DECIMAL(15,2) NOT NULL DEFAULT 0,invoice_required TINYINT(1) NOT NULL DEFAULT 1,invoice_requested VARCHAR(10) NOT NULL DEFAULT 'No',invoice_no VARCHAR(100) NOT NULL DEFAULT '',invoice_status VARCHAR(40) NOT NULL DEFAULT 'Pending',hard_copy_status VARCHAR(40) NOT NULL DEFAULT 'Pending',notes TEXT NULL,record_status VARCHAR(20) NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY booking_code(booking_code),KEY site_id(site_id),KEY site_code(site_code),KEY client_id(client_id),KEY start_date(start_date),KEY end_date(end_date),KEY record_status(record_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS validations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,site_id BIGINT UNSIGNED NOT NULL,validation_type VARCHAR(30) NOT NULL,validation_date DATE NULL,gps_attachment_id BIGINT UNSIGNED NULL,site_attachment_id BIGINT UNSIGNED NULL,newspaper_attachment_id BIGINT UNSIGNED NULL,day_attachment_id BIGINT UNSIGNED NULL,night_attachment_id BIGINT UNSIGNED NULL,validated_by BIGINT UNSIGNED NULL,notes TEXT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY campaign_id(campaign_id),KEY site_id(site_id),KEY validation_type(validation_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS electricity (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NULL,site_code VARCHAR(60) NOT NULL DEFAULT '',location VARCHAR(255) NOT NULL DEFAULT '',meter_no VARCHAR(100) NOT NULL DEFAULT '',size VARCHAR(60) NOT NULL DEFAULT '',service_number VARCHAR(100) NOT NULL DEFAULT '',t_number VARCHAR(100) NOT NULL DEFAULT '',bill_type VARCHAR(20) NOT NULL DEFAULT '',payment_amount DECIMAL(15,2) NOT NULL DEFAULT 0,billing_month VARCHAR(60) NOT NULL DEFAULT '',bill_date DATE NULL,due_date DATE NOT NULL,units DECIMAL(12,2) NOT NULL DEFAULT 0,rate DECIMAL(12,4) NOT NULL DEFAULT 0,other_charges DECIMAL(15,2) NOT NULL DEFAULT 0,amount DECIMAL(15,2) NOT NULL DEFAULT 0,payment_status VARCHAR(30) NOT NULL DEFAULT 'Pending',ecs VARCHAR(100) NOT NULL DEFAULT '',payment_date DATE NULL,paid_date DATE NULL,payment_reference VARCHAR(190) NOT NULL DEFAULT '',bill_attachment_id BIGINT UNSIGNED NULL,notes TEXT NULL,record_status VARCHAR(20) NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY site_id(site_id),KEY due_date(due_date),KEY payment_status(payment_status),KEY site_month(site_id,billing_month)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vendors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,service VARCHAR(120) NOT NULL DEFAULT 'Printing',contact_person VARCHAR(190) NOT NULL DEFAULT '',phone VARCHAR(60) NOT NULL DEFAULT '',email VARCHAR(190) NOT NULL DEFAULT '',cities TEXT NULL,rating DECIMAL(3,2) NOT NULL DEFAULT 4,notes TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY name(name),KEY service(service),KEY status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vendor_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vendor_id BIGINT UNSIGNED NOT NULL,campaign_id BIGINT UNSIGNED NULL,service VARCHAR(120) NOT NULL DEFAULT '',due_date DATE NULL,completed_date DATE NULL,on_time TINYINT(1) NOT NULL DEFAULT 0,quality_score DECIMAL(4,2) NOT NULL DEFAULT 0,notes TEXT NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY vendor_id(vendor_id),KEY campaign_id(campaign_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS proposals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proposal_code VARCHAR(80) NOT NULL UNIQUE,client_id BIGINT UNSIGNED NULL,client_name VARCHAR(190) NOT NULL DEFAULT '',campaign_name VARCHAR(190) NOT NULL DEFAULT '',proposal_date DATE NOT NULL,start_date DATE NULL,duration_days INT UNSIGNED NOT NULL DEFAULT 30,validity_days INT UNSIGNED NOT NULL DEFAULT 7,discount_percent DECIMAL(6,2) NOT NULL DEFAULT 0,tax_percent DECIMAL(6,2) NOT NULL DEFAULT 18,subtotal DECIMAL(15,2) NOT NULL DEFAULT 0,total DECIMAL(15,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'Draft',notes TEXT NULL,terms LONGTEXT NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY client_id(client_id),KEY status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS proposal_sites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proposal_id BIGINT UNSIGNED NOT NULL,site_id BIGINT UNSIGNED NOT NULL,site_code VARCHAR(60) NOT NULL,rate DECIMAL(15,2) NOT NULL DEFAULT 0,vendor_rate DECIMAL(15,2) NOT NULL DEFAULT 0,printing_rate DECIMAL(15,2) NOT NULL DEFAULT 0,notes TEXT NULL,KEY proposal_id(proposal_id),KEY site_id(site_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,client_id BIGINT UNSIGNED NULL,requested_date DATE NULL,invoice_no VARCHAR(120) NOT NULL DEFAULT '',invoice_date DATE NULL,invoice_amount DECIMAL(15,2) NOT NULL DEFAULT 0,invoice_status VARCHAR(40) NOT NULL DEFAULT 'Pending',hard_copy_required TINYINT(1) NOT NULL DEFAULT 0,hard_copy_status VARCHAR(40) NOT NULL DEFAULT 'Pending',courier_name VARCHAR(120) NOT NULL DEFAULT '',tracking_number VARCHAR(120) NOT NULL DEFAULT '',dispatch_date DATE NULL,delivered_date DATE NULL,payment_status VARCHAR(40) NOT NULL DEFAULT 'Pending',payment_date DATE NULL,notes TEXT NULL,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,record_status VARCHAR(20) NOT NULL DEFAULT 'active',KEY campaign_id(campaign_id),KEY invoice_status(invoice_status),KEY payment_status(payment_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NULL,campaign_id BIGINT UNSIGNED NULL,attachment_id BIGINT UNSIGNED NOT NULL,upload_type VARCHAR(50) NOT NULL,notes TEXT NULL,uploaded_by BIGINT UNSIGNED NULL,uploaded_at DATETIME NOT NULL,KEY site_id(site_id),KEY campaign_id(campaign_id),KEY upload_type(upload_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL DEFAULT 0,type VARCHAR(80) NOT NULL,object_type VARCHAR(50) NOT NULL DEFAULT '',object_id BIGINT UNSIGNED NULL,title VARCHAR(190) NOT NULL,message TEXT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,fingerprint VARCHAR(190) NOT NULL DEFAULT '',last_emailed_at DATETIME NULL,created_at DATETIME NOT NULL,KEY user_id(user_id),KEY is_read(is_read),UNIQUE KEY fingerprint(fingerprint)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS activity_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,user_name VARCHAR(190) NOT NULL DEFAULT '',action VARCHAR(120) NOT NULL,object_type VARCHAR(50) NOT NULL DEFAULT '',object_id BIGINT UNSIGNED NULL,old_value LONGTEXT NULL,new_value LONGTEXT NULL,created_at DATETIME NOT NULL,KEY user_id(user_id),KEY object_type(object_type),KEY created_at(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS occupancy_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_code VARCHAR(60) NOT NULL DEFAULT '',location VARCHAR(255) NOT NULL DEFAULT '',city VARCHAR(120) NOT NULL DEFAULT '',area VARCHAR(190) NOT NULL DEFAULT '',size VARCHAR(60) NOT NULL DEFAULT '',client VARCHAR(190) NOT NULL DEFAULT '',brand VARCHAR(190) NOT NULL DEFAULT '',display VARCHAR(190) NOT NULL DEFAULT '',month VARCHAR(60) NOT NULL DEFAULT '',start_date DATE NULL,end_date DATE NULL,days INT NOT NULL DEFAULT 30,occupancy_pct DECIMAL(5,2) NULL,total_amount DECIMAL(15,2) NOT NULL DEFAULT 0,pending DECIMAL(15,2) NOT NULL DEFAULT 0,po VARCHAR(100) NOT NULL DEFAULT '',bill VARCHAR(100) NOT NULL DEFAULT '',status VARCHAR(40) NOT NULL DEFAULT 'active',notes TEXT NULL,record_status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY site_code(site_code),KEY month(month),KEY record_status(record_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS storage_archives (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category VARCHAR(60) NOT NULL DEFAULT 'other',title VARCHAR(255) NOT NULL DEFAULT '',filename VARCHAR(255) NOT NULL DEFAULT '',file_url TEXT NULL,file_size VARCHAR(50) NOT NULL DEFAULT '—',format VARCHAR(40) NOT NULL DEFAULT 'other',meta_json LONGTEXT NULL,record_status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY category(category),KEY format(format),KEY record_status(record_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO settings(setting_key,setting_value,updated_at) VALUES
('company_name','Media Buzz',NOW()),('currency','INR',NOW()),('validation_interval','15',NOW()),('mounting_grace_days','3',NOW()),('electricity_due_soon_days','7',NOW()),('campaign_ending_warning_days','7',NOW()),('proposal_validity','7',NOW()),('proposal_tax','18',NOW())
ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW();
